#!/usr/bin/env bash
# Media of the demo projects of the concatenation (R.44/R.45): generated by the SYSTEM
# ffmpeg, not committed to the repository. testsrc2 — fine texture (text,
# cells, gradients), on which blur/sharpness are seen at once.
set -euo pipefail
cd "$(dirname "$0")"
ffmpeg -y -v error -f lavfi -i testsrc2=size=1280x720:rate=30 -t 12 \
  -pix_fmt yuv420p -c:v libx264 -crf 16 detail.mp4
# the right half — pure green (lime = 00FF00) under the greenscreen
ffmpeg -y -v error -f lavfi -i testsrc2=size=1280x720:rate=30 -t 12 \
  -vf "drawbox=x=640:y=0:w=640:h=720:color=lime@1:t=fill" \
  -pix_fmt yuv420p -c:v libx264 -crf 16 green.mp4
# R.46: the same material at 2560x1440 — four times as many pixels as in the
# 1280x720 project. On it the decode step is visible: zoom to 100 % takes the
# details of the FILE, not the blur of a frame compressed to Quality already during decode.
ffmpeg -y -v error -f lavfi -i testsrc2=size=2560x1440:rate=30 -t 12 \
  -pix_fmt yuv420p -c:v libx264 -crf 16 detail-hi.mp4
echo "ok: detail.mp4 green.mp4 detail-hi.mp4"
